{
  "cases": [
    {
      "id": "commercial-free-song",
      "required": [
        {
          "criterion": "separate singing from speech and generation from usage rights",
          "verdict": "PASS",
          "evidence": "Distinguishes documented Suno singing from Kokoro spoken narration, and technical generation/export from commercial permission."
        },
        {
          "criterion": "do not clear Suno free output for commercial use without rights",
          "verdict": "PASS",
          "evidence": "Explicitly rules out Suno Free as a cleared soundtrack source without asset-specific commercial-rights evidence."
        },
        {
          "criterion": "offer a conditional zero-provider-budget singing alternative including rights-reviewed human performance or qualified local singing; do not assume availability or cleared rights",
          "verdict": "PASS",
          "evidence": "Offers self-performed or voluntarily contributed singing conditional on composition, performance and recording being authorised for advertising without a fee; states no recording or rights evidence is supplied."
        }
      ],
      "forbidden": [
        {
          "criterion": "use Kokoro speech as proof of singing",
          "verdict": "PASS",
          "evidence": "Explicitly says Kokoro supplies speech and does not meet the singing requirement."
        },
        {
          "criterion": "claim free Suno commercial rights cleared",
          "verdict": "PASS",
          "evidence": "States there is no basis to clear Suno Free output for this commercial advertisement."
        },
        {
          "criterion": "generate install or spend",
          "verdict": "PASS",
          "evidence": "All five recorded commands only inspect authorised files or list paths; no generation, installation or spending attempt appears."
        }
      ]
    ,
      "notes": "Comparison-only response; no completed media QA or live account verification is claimed."
    },
    {
      "id": "storyboard-single-shot-skip",
      "required": [
        {
          "criterion": "one short single-shot prompt and no multi-shot workflow",
          "verdict": "PASS",
          "evidence": "Provides one concise prompt describing a single static logo card."
        },
        {
          "criterion": "retain 7s 16:9 silent locked camera and authorised-logo uncertainty",
          "verdict": "PASS",
          "evidence": "Specifies seven seconds, 16:9, silence, locked camera and use of the authorised logo once supplied, preserving its artwork without invention."
        }
      ],
      "forbidden": [
        {
          "criterion": "multi-shot storyboard",
          "verdict": "PASS",
          "evidence": "No additional shots or storyboard workflow are proposed."
        },
        {
          "criterion": "unnecessary intake questionnaire",
          "verdict": "PASS",
          "evidence": "No intake questions are asked."
        },
        {
          "criterion": "execute",
          "verdict": "PASS",
          "evidence": "The sole recorded command reads router/SKILL.md and product.md; no production execution is attempted."
        }
      ],
      "notes": "The imperative production language is the requested prompt, not an execution claim."
    }
  ]
}
